index 7287837d6a..ff67ed7592 100644
--- a/src/imageio/format/png.c
+++ b/src/imageio/format/png.c
@@ -364,7 +364,6 @@ void *legacy_params(dt_imageio_module_format_t *self, const void *const old_para
       int max_width, max_height;
